#!/usr/bin/env bash
# Primary-10 OSS release battery (post-hackathon).
# Requires: VERTEX_LOCATION=global, verityngn CLI, sb1507.mp4 for row 2.
# Stop on 0 claims.
# Resume: SKIP_PRIOR=1 SKIP_IDS=id1,id2 BATTERY_APPEND=1
# Do NOT edit this file while a battery process is running (bash re-reads source).
set -euo pipefail
ROOT="$(cd "$(dirname "$0")/.." && pwd)"
cd "$ROOT"
DATE="${BATTERY_DATE:-$(date -u +%Y-%m-%d)}"
OUT="${BATTERY_OUT:-$ROOT/outputs/release_v3_battery_$DATE}"
mkdir -p "$OUT"
export VERTEX_LOCATION="${VERTEX_LOCATION:-global}"
export PYTHONUNBUFFERED=1
LOG="$OUT/battery.log"
RESULTS="$OUT/results.jsonl"
if [[ "${BATTERY_APPEND:-0}" != "1" ]]; then
  : >"$RESULTS"
fi
echo "[$(date -u +%Y-%m-%dT%H:%M:%SZ)] START out=$OUT VERTEX_LOCATION=$VERTEX_LOCATION" | tee -a "$LOG"

should_skip() {
  local id="$1"
  case ",${SKIP_IDS:-}," in
    *,"$id",*) return 0 ;;
    *) return 1 ;;
  esac
}

count_claims() {
  local dest="$1"
  # Reports sometimes land only under outputs_debug; also accept metrics/claims_detailed.
  python3 -c "
from pathlib import Path
import json, shutil
d = Path(r'$dest')
vid = d.name
root = Path(r'$ROOT')
cands = sorted(p for p in d.glob('*_report.json') if 'final_report' not in p.name)
if not cands:
    dbg = root / 'outputs_debug' / vid
    if dbg.is_dir():
        for p in sorted(dbg.rglob('*_report.json'), reverse=True):
            if 'final_report' in p.name:
                continue
            # Sync canonical artifacts into dest for the battery pack.
            for src in p.parent.glob(vid + '_*'):
                if src.is_file():
                    shutil.copy2(src, d / src.name)
            if (p.parent / 'report.html').is_file():
                shutil.copy2(p.parent / 'report.html', d / 'report.html')
            cands = [d / p.name]
            break
if cands and (d / cands[0].name).is_file():
    data = json.load(open(d / cands[0].name))
    print(len(data.get('claims_breakdown') or data.get('claims') or []))
elif (d / f'{vid}_metrics.json').is_file():
    print(int(json.load(open(d / f'{vid}_metrics.json')).get('n_claims') or 0))
elif (d / f'{vid}_claims_detailed.json').is_file():
    print(len(json.load(open(d / f'{vid}_claims_detailed.json'))))
else:
    print(0)
" 2>/dev/null || echo 0
}

run_yt() {
  local id="$1" title="$2" tier="${3:-full}"
  if should_skip "$id"; then
    echo "[$(date -u +%Y-%m-%dT%H:%M:%SZ)] SKIP $id (SKIP_IDS)" | tee -a "$LOG"
    return 0
  fi
  local dest="$OUT/$id"
  mkdir -p "$dest"
  echo "[$(date -u +%Y-%m-%dT%H:%M:%SZ)] RUN $id tier=$tier" | tee -a "$LOG"
  local rc=0
  verityngn analyze --tier "$tier" --deep \
    "https://www.youtube.com/watch?v=${id}" \
    --title "$title" \
    -o "$dest" >>"$LOG" 2>&1 || rc=$?
  local claims
  claims="$(count_claims "$dest")"
  python3 -c "import json;print(json.dumps({'id':'$id','title':'''$title''','tier':'$tier','rc':$rc,'claims':int('$claims'),'out':'$dest'}))" >>"$RESULTS"
  echo "[$(date -u +%Y-%m-%dT%H:%M:%SZ)] DONE $id rc=$rc claims=$claims" | tee -a "$LOG"
  if [[ "$claims" == "0" ]]; then
    echo "STOP: 0 claims on $id — fix Vertex/location before continuing" | tee -a "$LOG"
    exit 2
  fi
}

run_local() {
  local id="$1" file="$2" title="$3"
  if should_skip "$id"; then
    echo "[$(date -u +%Y-%m-%dT%H:%M:%SZ)] SKIP $id (SKIP_IDS)" | tee -a "$LOG"
    return 0
  fi
  local dest="$OUT/$id"
  mkdir -p "$dest"
  echo "[$(date -u +%Y-%m-%dT%H:%M:%SZ)] RUN local $id" | tee -a "$LOG"
  local rc=0
  verityngn analyze --tier local-full --deep \
    -f "$file" --title "$title" -o "$dest" >>"$LOG" 2>&1 || rc=$?
  local claims
  claims="$(count_claims "$dest")"
  python3 -c "import json;print(json.dumps({'id':'$id','title':'''$title''','tier':'local-full','rc':$rc,'claims':int('$claims'),'out':'$dest'}))" >>"$RESULTS"
  echo "[$(date -u +%Y-%m-%dT%H:%M:%SZ)] DONE $id rc=$rc claims=$claims" | tee -a "$LOG"
  if [[ "$claims" == "0" ]]; then
    echo "STOP: 0 claims on $id" | tee -a "$LOG"
    exit 2
  fi
}

if [[ "${SKIP_PRIOR:-1}" != "1" ]]; then
  run_yt "tLJC8hkK-ao" "Lipozem" "full"
  SB1507="${SB1507_MP4:-/Users/ajjc/Downloads/sb1507.mp4}"
  run_local "sb1507" "$SB1507" "SB1507 Oregon QSBS"
else
  echo "[$(date -u +%Y-%m-%dT%H:%M:%SZ)] SKIP prior Lipozem + SB1507 (SKIP_PRIOR=1)" | tee -a "$LOG"
fi

run_yt "V7mYWOzdhpc" "Alex Karp CNBC tech dominance"
run_yt "ijRuuaaM6XM" "Karp Huang Power Lunch"
# Primary fuq0Ncdsknk is a ~12h CES LIVE restream (N18G); Vertex 500s after seg1.
# Slate backup #15: Huang Squawk AMD/OpenAI.
run_yt "cP8pfCJTw4Q" "Jensen Huang Squawk AMD OpenAI"
run_yt "dRgPbNJ5RJc" "Alex Karp WEF 2026"
run_yt "lb_ZJylekWo" "Satya Nadella Stargate Squawk"
run_yt "tSdWpsj1Cyo" "Odd Lots Franchise Gig Economy"
run_yt "7MXE1kDCY-k" "Butler Kahn Expert Deposition"
run_yt "RuinHdlpXvE" "Scott Carney Peptides Lab"

echo "[$(date -u +%Y-%m-%dT%H:%M:%SZ)] battery complete" | tee -a "$LOG"
